{
  "findings": [
    {
      "check_id": "CKV_AZURE_23",
      "title": "Database should have long-term backup retention enabled",
      "resource": "azurerm_mssql_database.trading_database",
      "severity": "HIGH",
      "explanation": "The database does not have long-term backup retention enabled. This increases the risk of data loss in case of accidental deletion or corruption."
    },
    {
      "check_id": "CKV_AZURE_24",
      "title": "Database should have zone redundancy enabled",
      "resource": "azurerm_mssql_database.trading_database",
      "severity": "HIGH",
      "explanation": "Zone redundancy is disabled, which means the database is not resilient to zone-level failures. This can lead to downtime or data unavailability in case of an outage in the availability zone."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_database\" \"trading_database\" {\n  name           = \"trading-database\"\n  server_id      = azurerm_mssql_server.trading_sql_server.id\n  collation      = \"SQL_Latin1_General_CP1_CI_AS\"\n  license_type   = \"LicenseIncluded\"\n  max_size_gb    = 100\n  sku_name       = \"S2\"\n  zone_redundant = true\n\n  long_term_retention_policy {\n    weekly_retention = \"P1W\"\n    monthly_retention = \"P1M\"\n    yearly_retention = \"P1Y\"\n    week_of_year = 1\n  }\n}",
  "fix_summary": "Enabled zone redundancy for the database to improve resilience against zone-level failures. Added a long-term retention policy to ensure backups are retained for weekly, monthly, and yearly periods, reducing the risk of data loss."
}
